    public static int ptWidth(int kind, int arg) {
        // How many cells a field of the dump table covers.
        if (kind == 3) {
            return 4;
        }
        if ((kind == 4) || (kind == 5)) {
            return 2;
        }
        if (kind == 7) {
            return arg;
        }
        return 1;
    }
    public static void testEveryCellIsPrintedOrNamedSpare() {
        // per arena of the field table: the cells its rows cover, plus its spare cells, are its stride, and no two rows overlap
        int a = 0;
        int k = 0;
        int covered = 0;
        int next = 0;
        int f = 0;
        while (a < 6) {
            covered = 0;
            next = 0;
            k = 0;
            while (k < Player.PL_FX[a * 4 + 1]) {
                f = Player.PL_FD[(Player.PL_FX[a * 4 + 0] + k) * 6 + 1];
                emon.Testport.assertThat(f >= next, "the fields are in stride order and do not overlap");
                covered += ptWidth(Player.PL_FD[(Player.PL_FX[a * 4 + 0] + k) * 6 + 2], Player.PL_FD[(Player.PL_FX[a * 4 + 0] + k) * 6 + 5]);
                next = f + ptWidth(Player.PL_FD[(Player.PL_FX[a * 4 + 0] + k) * 6 + 2], Player.PL_FD[(Player.PL_FX[a * 4 + 0] + k) * 6 + 5]);
                k += 1;
            }
            emon.Testport.assertEq(covered + Player.PL_FX[a * 4 + 3], Player.PL_FX[a * 4 + 2], "printed plus spare is the stride");
            a += 1;
        }
        emon.Testport.assertEq(a, 6, "six arenas");
    }
